#include <cstddef>
#include <cstdint>
typedef struct { std::int64_t key; int left,right,npl; } Node;
static int merge_nodes(Node *a,int x,int y){if(x<0)return y;if(y<0)return x;if(a[x].key>a[y].key){int t=x;x=y;y=t;}a[x].right=merge_nodes(a,a[x].right,y);if(a[x].left<0){a[x].left=a[x].right;a[x].right=-1;}else{if(a[a[x].left].npl<a[a[x].right].npl){int t=a[x].left;a[x].left=a[x].right;a[x].right=t;}a[x].npl=a[a[x].right].npl+1;}return x;}
double leftist_heap(const std::int64_t*v,std::size_t n){if(n<1||n>43)return -1e300;std::int64_t m=v[0];if(m<0||m>14||n!=(std::size_t)(1+3*m))return -1e300;Node a[14];int roots[2]={-1,-1},used=0,ex=0;std::int64_t result=0;for(std::int64_t i=0;i<m;i++){std::int64_t k=v[1+3*i],h=v[2+3*i],z=v[3+3*i];if(k<0||k>3)return -1e300;if(k==0){if(h<0||h>1||z<0||z>9)return -1e300;a[used]=(Node){z,-1,-1,0};roots[h]=merge_nodes(a,used++,roots[h]);}else if(k==1){if(h<0||h>1||z!=0||++ex>10)return -1e300;int r=roots[h],got=-1;if(r>=0){got=(int)a[r].key;roots[h]=merge_nodes(a,a[r].left,a[r].right);}result=result*13+got+2;}else if(k==2){if(h!=0||z!=0)return -1e300;roots[0]=merge_nodes(a,roots[0],roots[1]);roots[1]=-1;}else{if(h<0||h>1||z!=0)return -1e300;roots[h]=-1;}}return (double)result;}
